<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3';
import { computed, ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import Breadcrumbs from '../../../components/admin/Breadcrumbs.vue';
import EmptyState from '../../../components/admin/EmptyState.vue';
import PageHeader from '../../../components/admin/PageHeader.vue';
import Pagination from '../../../components/admin/Pagination.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';

interface Row { location_id: string; variant_id: string; location_name: string; location_code: string; product_name: string; variant_name: string | null; sku: string; on_hand: number; status: 'ACTIVE' | 'UNINITIALIZED'; average_unit_cost: string | null; inventory_value: string | null; currency: string | null }
interface PageLink { url: string | null; label: string; active: boolean }
const props = defineProps<{ valuations: { data: Row[]; links: PageLink[]; from?: number | null; to?: number | null; total?: number }; totals: Array<{ currency: string; inventory_value: string }>; filters: { search: string } }>();
const { t } = useI18n();
const search = ref(props.filters.search ?? '');
const searching = ref(false);
const hasSearch = computed(() => props.filters.search !== '');
const uninitializedCount = computed(() => props.valuations.data.filter((row) => row.status === 'UNINITIALIZED').length);
watch(() => props.filters.search, (value) => { search.value = value; });
const visit = (value: string) => router.get('/admin/inventory/valuation', value.trim() ? { search: value.trim() } : {}, { preserveState: true, replace: true, onStart: () => { searching.value = true; }, onFinish: () => { searching.value = false; } });
const submit = () => visit(search.value);
const clearSearch = () => { search.value = ''; visit(''); };
</script>

<template>
    <Head :title="t('inventory.valuation.title')" />
    <AdminLayout><section class="mx-auto grid w-full max-w-[90rem] gap-5 sm:gap-6">
        <Breadcrumbs :items="[{ label: t('nav.operations') }, { label: t('inventory.title'), href: '/admin/inventory' }, { label: t('inventory.valuation.title') }]" />
        <PageHeader :title="t('inventory.valuation.title')" :eyebrow="t('common.allCompany')" :description="t('inventory.valuation.description')"><template #actions><Link href="/admin/inventory" class="inline-flex min-h-9 items-center justify-center rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold text-admin-text-secondary hover:bg-slate-50">{{ t('inventory.back') }}</Link></template></PageHeader>
        <div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><article v-for="total in totals" :key="total.currency" class="admin-card p-4"><p class="admin-label">{{ t('inventory.valuation.totalValue') }}</p><p class="mt-2 font-mono text-xl font-semibold tabular-nums text-admin-primary">{{ total.currency }} {{ total.inventory_value }}</p><p class="mt-1 text-xs text-admin-neutral">{{ t('inventory.valuation.initializedOnly') }}</p></article><article v-if="!totals.length" class="admin-card p-4 sm:col-span-2"><p class="admin-label">{{ t('inventory.valuation.totalValue') }}</p><p class="mt-2 text-sm font-semibold text-admin-neutral">{{ t('inventory.valuation.noTotals') }}</p></article></div>
        <aside v-if="uninitializedCount" class="rounded-md border border-admin-warning-border bg-admin-warning-bg px-4 py-3"><p class="text-sm font-semibold text-admin-text">{{ t('inventory.valuation.uninitializedVisible', { count: uninitializedCount }) }}</p><p class="mt-0.5 text-xs leading-5 text-admin-text-secondary">{{ t('inventory.valuation.uninitializedHelp') }}</p></aside>
        <form class="admin-card flex flex-col gap-3 p-3 sm:flex-row sm:items-end sm:p-4" role="search" @submit.prevent="submit"><label for="valuation-search" class="grid min-w-0 flex-1 gap-1.5"><span class="admin-label">{{ t('inventory.valuation.search') }}</span><input id="valuation-search" v-model="search" type="search" autocomplete="off" :placeholder="t('inventory.valuation.searchPlaceholder')" class="admin-control w-full px-3 text-sm" /></label><div class="flex gap-2"><button type="submit" :disabled="searching" class="min-h-9 flex-1 rounded-md bg-admin-primary px-4 text-sm font-semibold text-white disabled:opacity-60 sm:flex-none">{{ searching ? t('common.searching') : t('common.search') }}</button><button v-if="hasSearch" type="button" :disabled="searching" class="min-h-9 flex-1 rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold text-admin-text-secondary sm:flex-none" @click="clearSearch">{{ t('common.clear') }}</button></div></form>
        <template v-if="valuations.data.length"><div class="admin-card hidden overflow-hidden lg:block"><table class="admin-table w-full table-fixed text-left text-xs"><thead><tr><th class="w-[26%] p-3">{{ t('inventory.productVariant') }}</th><th class="w-[20%] p-3">{{ t('inventory.location') }}</th><th class="w-[10%] p-3 text-right">{{ t('inventory.onHand') }}</th><th class="w-[14%] p-3">{{ t('common.status') }}</th><th class="w-[15%] p-3 text-right">{{ t('inventory.averageCost') }}</th><th class="w-[15%] p-3 text-right">{{ t('inventory.inventoryValue') }}</th></tr></thead><tbody class="divide-y divide-admin-border"><tr v-for="row in valuations.data" :key="`${row.location_id}-${row.variant_id}`"><td class="p-3"><Link :href="`/admin/inventory/variants/${row.variant_id}`" class="block truncate text-sm font-semibold text-admin-text hover:text-admin-secondary">{{ row.product_name }}</Link><p class="mt-0.5 truncate font-mono text-[10px] text-admin-neutral">{{ row.sku }}<template v-if="row.variant_name"> · {{ row.variant_name }}</template></p></td><td class="p-3"><p class="font-medium text-admin-text-secondary">{{ row.location_name }}</p><p class="mt-0.5 font-mono text-[10px] text-admin-neutral">{{ row.location_code }}</p></td><td class="p-3 text-right font-mono font-semibold tabular-nums">{{ row.on_hand }}</td><td class="p-3"><span class="rounded border px-1.5 py-0.5 font-mono text-[10px] font-medium" :class="row.status === 'ACTIVE' ? 'border-admin-success-border bg-admin-success-bg text-admin-success' : 'border-admin-warning-border bg-admin-warning-bg text-admin-warning'">{{ t(`inventory.costStatuses.${row.status}`) }}</span></td><td class="p-3 text-right font-mono tabular-nums">{{ row.average_unit_cost === null ? '—' : `${row.currency} ${row.average_unit_cost}` }}</td><td class="p-3 text-right font-mono font-semibold tabular-nums">{{ row.inventory_value === null ? '—' : `${row.currency} ${row.inventory_value}` }}</td></tr></tbody></table></div>
            <div class="grid gap-2.5 lg:hidden"><article v-for="row in valuations.data" :key="`mobile-${row.location_id}-${row.variant_id}`" class="admin-card p-4"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><Link :href="`/admin/inventory/variants/${row.variant_id}`" class="block truncate text-sm font-semibold text-admin-text">{{ row.product_name }}</Link><p class="mt-1 truncate font-mono text-[10px] text-admin-neutral">{{ row.sku }}<template v-if="row.variant_name"> · {{ row.variant_name }}</template></p></div><span class="shrink-0 rounded border px-1.5 py-0.5 font-mono text-[10px] font-medium" :class="row.status === 'ACTIVE' ? 'border-admin-success-border bg-admin-success-bg text-admin-success' : 'border-admin-warning-border bg-admin-warning-bg text-admin-warning'">{{ t(`inventory.costStatuses.${row.status}`) }}</span></div><p class="mt-3 border-t border-admin-border pt-3 text-xs font-medium text-admin-text-secondary">{{ row.location_name }} · <span class="font-mono">{{ row.location_code }}</span></p><dl class="mt-3 grid grid-cols-3 gap-2"><div><dt class="admin-label">{{ t('inventory.onHand') }}</dt><dd class="mt-1 font-mono text-xs font-semibold">{{ row.on_hand }}</dd></div><div><dt class="admin-label">{{ t('inventory.averageCost') }}</dt><dd class="mt-1 font-mono text-xs font-semibold">{{ row.average_unit_cost === null ? '—' : `${row.currency} ${row.average_unit_cost}` }}</dd></div><div><dt class="admin-label">{{ t('inventory.inventoryValue') }}</dt><dd class="mt-1 font-mono text-xs font-semibold">{{ row.inventory_value === null ? '—' : `${row.currency} ${row.inventory_value}` }}</dd></div></dl></article></div></template>
        <EmptyState v-else :title="hasSearch ? t('inventory.valuation.noMatch') : t('inventory.valuation.empty')" :description="hasSearch ? t('inventory.valuation.noMatchHelp') : t('inventory.valuation.emptyHelp')"><template v-if="hasSearch" #actions><button type="button" class="admin-link text-sm" @click="clearSearch">{{ t('inventory.clearSearch') }}</button></template></EmptyState>
        <Pagination :links="valuations.links" :from="valuations.from" :to="valuations.to" :total="valuations.total" />
    </section></AdminLayout>
</template>
